369	369 │ // ---- prune ----------------------------------------------------------------------------------------------------
370	370 │ 
371	371 │ export interface PruneOptions { dryRun?: boolean; minAgeMs?: number; limit?: number; discardIgnored?: boolean }
372	372 │ 
373	373 │ const DAY_MS = 86_400_000;
374	374 │ const REPORT_LINES = 40;
375	375 │ 
376	376 │ export function parseAge(text: string): number {
377	377 │   const match = /^(\d+)([smhdw])$/.exec(text);
378	378 │   if (!match) throw new WorktreeError("--min-age must look like 30m, 12h, 1d or 2w");
379	379 │   const unit = { s: 1000, m: 60_000, h: 3_600_000, d: DAY_MS, w: 7 * DAY_MS }[match[2] as "s"];
380	380 │   return Number(match[1]) * unit;
381	381 │ }
382	382 │ 
383	383 │ export function pruneWorktrees(ctx: WorktreeContext, options: PruneOptions = {}): CommandResult {
384	384 │   const minAge = options.minAgeMs ?? DAY_MS;
385	385 │   const limit = Math.max(1, options.limit ?? 100);
386	386 │   const repo = openRepo(ctx.cwd);
387	387 │   const here = currentEntry(repo);
388	388 │   const target = defaultBranch(repo);
389	389 │   const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
390	390 │   if (!targetSha) throw new WorktreeError("this repository has no default branch to compare against");
391	391 │ 
392	392 │   const lines: string[] = [];
393	393 │   const counts = { removed: 0, kept: 0, young: 0, stale: 0 };
394	394 │   let limited = false;
395	395 │   const label = (entry: WorktreeEntry) => (entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path));
396	396 │   const keep = (entry: WorktreeEntry, why: string) => { counts.kept++; lines.push(`kept ${label(entry)}: ${why}`); };
397	397 │   const now = Date.now();
398	398 │ 
399	399 │   for (const entry of repo.entries) {
400	400 │     if (entry.isMain || entry === here) continue;
401	401 │     if (counts.removed >= limit) { limited = true; break; }
402	402 │     if (entry.prunable && entry.locked) { keep(entry, "stale but locked"); continue; }
403	403 │     if (entry.prunable) {
404	404 │       // A hand-deleted worktree is judged like any other. A detached one may hold the only reference to commits in its
405	405 │       // administrative HEAD and reflog, so it goes only if that HEAD is integrated and old enough; a branch worktree's
406	406 │       // commits live on its branch, which stays. Only the selected entries are cleared, never a global `worktree prune`.
407	407 │       try {
408	408 │         const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000;
409	409 │         if (entry.detached && now - stamp < minAge) { counts.young++; continue; }
410	410 │         const reason = entry.detached ? integratedReason(repo, entry.head, targetSha) : "branch kept";
411	411 │         if (!reason) { keep(entry, `stale, but its detached HEAD is not merged into ${shownBranch(target!)}`); continue; }
412	412 │         if (!options.dryRun) clearStaleEntry(repo, entry);
413	413 │         counts.stale++;
414	414 │         counts.removed++;
415	415 │         lines.push(`${options.dryRun ? "would clear" : "cleared"} stale ${label(entry)} (${reason})`);
416	416 │       } catch (err) {
417	417 │         keep(entry, redactSecrets((err as Error).message).slice(0, 160));
418	418 │       }
419	419 │       continue;
420	420 │     }
421	421 │     if (entry.locked) { keep(entry, "locked"); continue; }
422	422 │     if (isSpeculativeEntry(repo, entry)) { keep(entry, "speculative task worktree"); continue; }
423	423 │     try {
424	424 │       const touched = Math.max(fs.statSync(entry.path).mtimeMs, Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: 5000 })) * 1000);
425	425 │       if (now - touched < minAge) { counts.young++; continue; }
426	426 │       const reason = integratedReason(repo, entry.head, targetSha);
427	427 │       if (!reason) { keep(entry, `not merged into ${shownBranch(target!)}`); continue; }
428	428 │       const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
429	429 │       if (dirty.total > 0) { keep(entry, `dirty (${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked)`); continue; }
430	430 │       if (dirty.ignored > 0 && !options.discardIgnored) { keep(entry, `${dirty.ignored} ignored path(s); pass --discard-ignored to prune it anyway`); continue; }
431	431 │       if (options.dryRun) {
432	432 │         counts.removed++;
433	433 │         lines.push(`would remove ${label(entry)} (integrated: ${reason})`);
434	434 │         continue;
435	435 │       }
436	436 │       removeOne(ctx, entry.path, { discardIgnored: dirty.ignored > 0 });
437	437 │       counts.removed++;
438	438 │       lines.push(`removed ${label(entry)} (integrated: ${reason})`);
439	439 │     } catch (err) {
440	440 │       keep(entry, redactSecrets((err as Error).message).slice(0, 160));
441	441 │     }
442	442 │   }
443	443 │ 
444	444 │   const summary = `${options.dryRun ? "Would remove" : "Removed"} ${counts.removed}, kept ${counts.kept}, ${counts.young} younger than the minimum age${counts.stale ? `, ${counts.stale} stale registration(s) ${options.dryRun ? "would be pruned" : "pruned"}` : ""}.`;
445	445 │   const shown = lines.slice(0, REPORT_LINES);
446	446 │   if (lines.length > REPORT_LINES) shown.push(`... ${lines.length - REPORT_LINES} more lines`);
447	447 │   if (limited) shown.push(`stopped at the limit of ${limit} removals; run prune again for more`);
448	448 │   return { success: true, output: [...shown, summary].join("\n"), data: { ...counts, limited } };
449	449 │ }
